ruleExplore.author:
@js:var entries = result.match(/<entry>[\s\S]*?<\/entry>/g) || [];
var books = entries.map(function(entry) {
  var m;
  var title = (m = entry.match(/<title>([^<]+)<\/title>/)) ? m[1] : '';
  var author = (m = entry.match(/<author>[\s\S]*?<name>([^<]+)<\/name>/)) ? m[1] : '';
  var cover = (m = entry.match(/href="([^"]+)"[^>]*rel="http:\/\/opds-spec.org\/image"/)) ? m[1] : '';
  var bookUrl = (m = entry.match(/rel="http:\/\/opds-spec.org\/acquisition"[^>]*href="([^"]+)"/)) ? m[1] : '';
  var intro = (m = entry.match(/<content[^>]*>[\s\S]*?<p>([^<]+)<\/p>/)) ? m[1] : '';
  return {name: title, author: author, bookUrl: bookUrl, coverUrl: cover, intro: intro};
});
JSON.stringify(books)

